Task ID: java_path_body_id_mismatch
Scenario: Controller trusts request body identifier over path identifier.

Instructions:
Find the most dangerous API contract bug and give the minimal fix. Assume this endpoint is public and used by multiple clients.

Project snapshot:

=== File: src/main/java/com/example/account/UpdateAccountRequest.java ===
package com.example.account;

public class UpdateAccountRequest {
    private Long accountId;
    private String displayName;

    public Long getAccountId() {
        return accountId;
    }

    public void setAccountId(Long accountId) {
        this.accountId = accountId;
    }

    public String getDisplayName() {
        return displayName;
    }

    public void setDisplayName(String displayName) {
        this.displayName = displayName;
    }
}

=== File: src/main/java/com/example/account/AccountController.java ===
package com.example.account;

public class AccountController {
    private final AccountService accountService;

    public AccountController(AccountService accountService) {
        this.accountService = accountService;
    }

    public AccountDto update(long pathAccountId, UpdateAccountRequest request) {
        return accountService.update(request.getAccountId(), request.getDisplayName());
    }
}

=== File: src/main/java/com/example/account/AccountService.java ===
package com.example.account;

public class AccountService {
    private final AccountRepository accountRepository;

    public AccountService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    public AccountDto update(long accountId, String displayName) {
        Account account = accountRepository.require(accountId);
        account.setDisplayName(displayName);
        accountRepository.save(account);
        return new AccountDto(account.getId(), account.getDisplayName());
    }
}
